// Checks on the redactor plugin, which is generated by scripts/sync-redactor.mjs from
// apra-redactor-mcp's marketplace-plugin/ folder. This tests folder is the only part of
// plugins/redactor/ maintained here.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkVersions, MARKER } from '../../../scripts/sync-redactor.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const PLUGIN = path.join(here, '..');
const ROOT = path.join(PLUGIN, '..', '..');
const read = (...p) => fs.readFileSync(path.join(PLUGIN, ...p), 'utf8');
const json = (...p) => JSON.parse(read(...p));

const manifest = json('.claude-plugin', 'plugin.json');
const mcp = json('.mcp.json');
const entry = JSON.parse(fs.readFileSync(path.join(ROOT, '.claude-plugin', 'marketplace.json'), 'utf8'))
  .plugins.find((p) => p.name === 'redactor');

function pluginFiles(dir = PLUGIN, prefix = '') {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = prefix ? `${prefix}/${e.name}` : e.name;
    if (e.isDirectory()) { if (rel !== 'tests') out.push(...pluginFiles(path.join(dir, e.name), rel)); }
    else out.push(rel);
  }
  return out;
}

test('manifest', () => {
  assert.equal(manifest.name, 'redactor');
  assert.match(manifest.version, /^\d+\.\d+\.\d+$/);
  assert.equal(manifest.license, 'Apache-2.0');
  assert.equal(manifest.author.name, 'Apra Labs');
  assert.equal(manifest.homepage, 'https://github.com/Apra-Labs/agent-marketplace/tree/main/plugins/redactor');
  assert.ok(manifest.keywords.length > 0);
  assert.match(manifest.description, /\buv\b/);
});

test('license is Apache-2.0', () => {
  const text = read('LICENSE');
  assert.match(text, /Apache License\s+Version 2\.0, January 2004/);
  assert.match(text, /Copyright \d{4} Apra Labs/);
});

test('.mcp.json launches the pinned PyPI release with uvx', () => {
  assert.deepEqual(Object.keys(mcp), ['mcpServers']);
  // The key is the server name the redacted-tools skill refers to.
  assert.deepEqual(Object.keys(mcp.mcpServers), ['apra-redactor']);
  const s = mcp.mcpServers['apra-redactor'];
  assert.equal(s.command, 'uvx');
  assert.deepEqual(s.args, ['--from', `apra-redactor-mcp==${manifest.version}`, 'apra-redactor-mcp', 'serve']);
  assert.match(read('skills', 'redacted-tools', 'SKILL.md'), /`apra-redactor`/);
});

test('one version in plugin.json, marketplace.json, .mcp.json and the marker', () => {
  assert.ok(entry, 'marketplace.json has a redactor entry');
  assert.equal(entry.version, manifest.version);
  assert.equal(checkVersions(new Map([
    ['.claude-plugin/plugin.json', Buffer.from(JSON.stringify(manifest))],
    ['.mcp.json', Buffer.from(JSON.stringify(mcp))],
  ]), manifest.version), manifest.version);
  assert.match(read(MARKER), new RegExp(`^- version: ${manifest.version.replace(/\./g, '\\.')}$`, 'm'));
});

test('marketplace entry', () => {
  assert.equal(entry.source, './plugins/redactor');
  assert.equal(entry.category, 'security');
  assert.match(entry.description, /\buv\b/);
  assert.match(entry.description, /no apra-fleet needed/);
  assert.ok(entry.keywords.length > 0);
});

test('the sync refuses mismatched versions', () => {
  const files = (pluginVersion, pin, name = 'redactor') => new Map([
    ['.claude-plugin/plugin.json', Buffer.from(JSON.stringify({ name, version: pluginVersion }))],
    ['.mcp.json', Buffer.from(JSON.stringify({ mcpServers: { 'apra-redactor': { command: 'uvx', args: ['--from', `apra-redactor-mcp==${pin}`, 'apra-redactor-mcp', 'serve'] } } }))],
  ]);
  assert.equal(checkVersions(files('1.2.3', '1.2.3'), '1.2.3'), '1.2.3');
  assert.throws(() => checkVersions(files('1.2.3', '1.2.3'), '1.2.4'), /pyproject/);
  assert.throws(() => checkVersions(files('1.2.3', '1.2.2'), '1.2.3'), /pins apra-redactor-mcp==1\.2\.2/);
  assert.throws(() => checkVersions(files('1.2.3', '1.2.3', 'other'), '1.2.3'), /name/);
});

test('generated folder carries its do-not-edit marker', () => {
  assert.match(read(MARKER), /do not edit/i);
  assert.match(read(MARKER), /scripts\/sync-redactor\.mjs/);
});

test('launch config has no machine-specific paths', () => {
  for (const f of ['.mcp.json', '.claude-plugin/plugin.json']) {
    const text = read(f);
    assert.doesNotMatch(text, /\$\{?(HOME|USERPROFILE|APPDATA)\}?|%[A-Z]+%|~[\\/]/, f);
    assert.doesNotMatch(text, /[A-Za-z]:\\\\|"\/(home|Users|opt|usr)\//, f);
  }
  for (const f of pluginFiles()) {
    if (f === 'LICENSE') continue;
    assert.doesNotMatch(read(...f.split('/')), /~\/\.claude\/|\.claude[\\/]plugins[\\/]cache/, f); // rule 2
  }
});

test('public-safe: only known public hosts, no private IPs (rule 8)', () => {
  const allowed = new Set([
    'github.com', 'docs.astral.sh', 'astral.sh', 'pypi.org', 'modelcontextprotocol.io',
    'apralabs.com', 'www.apache.org', 'mcp.example.com',
  ]);
  for (const f of pluginFiles()) {
    const text = read(...f.split('/'));
    for (const [, host] of text.matchAll(/https?:\/\/([^/\s)"'`>]+)/g)) {
      assert.ok(allowed.has(host.toLowerCase()), `${f}: unexpected host ${host}`);
    }
    assert.doesNotMatch(text, /\b(10\.\d+|192\.168|172\.(1[6-9]|2\d|3[01]))\.\d+\.\d+\b/, f);
    assert.doesNotMatch(text, /\b[\w-]+\.(internal|corp|lan|local)\b/i, f);
    assert.doesNotMatch(text, /bitbucket\.org\/|dev\.azure\.com|visualstudio\.com/, f);
  }
});
